53	constexpr float kWalkSpeed = 7.0f;       // units (~meters) per second
54	constexpr float kPlayerRadius = 0.45f;   // collision circle on the ground
55	constexpr float kTalkRadius = 3.5f;      // how close "press T to talk" works
56	constexpr float kNameplateRange = 28.f;  // how far name tags stay visible
57	constexpr float kMouseSensitivity = 0.12f;
58	constexpr float kMaxPitchDeg = 75.f;
59	// How long an arrest holds the player at the police station. Short, because
60	// the worst on-the-books offense here is disturbing the peace.
61	constexpr float kJailSeconds = 10.f;
62	
63	// What the main loop is currently showing.
64	enum class AppMode { Playing, Dialogue, Menu, Dead };
65	
66	// First-person pose; position is the FEET on the ground plane (y = 0).
67	struct LocalPlayer {
68	    Vec3 position{0.f, 0.f, 24.f};  // plaza south edge
69	    float yawDeg = 0.f;
70	    float pitchDeg = 0.f;
71	};
72	
73	// A short in-world text line above an NPC's head, spawned by combat events.
74	struct CombatCallout {
75	    int npcIndex = -1;
76	    std::string text;
77	    float ttl = 3.f;  // seconds before it fades
78	};
79	
80	// Walks up from the working directory until config/llm.cfg is found so the
81	// binary can be launched from build/ or the project root.
82	fs::path findProjectRoot() {
83	    fs::path root = fs::current_path();
84	    for (int i = 0; i < 4; ++i) {
85	        if (fs::exists(root / "config" / "llm.cfg")) break;
86	        if (root.has_parent_path()) root = root.parent_path();
87	    }
88	    return root;
89	}
90	
91	// Unit forward vector on the ground plane for a yaw in degrees.
92	Vec3 flatForward(float yawDeg) {
93	    return normalize(Vec3{std::sin(degToRad(yawDeg)), 0.f, std::cos(degToRad(yawDeg))});
94	}
95	
96	// Ground-plane right vector; must match the camera basis or strafe inverts.
97	Vec3 flatRight(float yawDeg) {
98	    const Vec3 f = flatForward(yawDeg);
99	    return Vec3{-f.z, 0.f, f.x};
100	}
101	
102	// One frame of mouse look from raylib's relative mouse delta.
103	void applyMouseLook(LocalPlayer& pose) {
104	    const Vector2 delta = GetMouseDelta();
105	    // Mouse-right lowers yaw: right-handed basis, yaw grows toward +X.
106	    pose.yawDeg -= delta.x * kMouseSensitivity;
107	    pose.pitchDeg = clampf(pose.pitchDeg - delta.y * kMouseSensitivity,
108	                           -kMaxPitchDeg, kMaxPitchDeg);
109	}
110	
111	// A short third-person description of an action an NPC just took, shown in
112	// the transcript so a wordless tag-only reply still gives feedback.
113	std::string stageDirection(NpcAction action) {
114	    switch (action) {
115	        case NpcAction::Follow: return "falls into step with you.";
116	        case NpcAction::Stop: return "stops and stays put.";
117	        case NpcAction::Face: return "turns to face you.";
118	        case NpcAction::RaiseHand: return "raises their right hand.";
119	        case NpcAction::Wave: return "waves at you.";
120	        case NpcAction::Arrest: return "moves to apprehend you!";
121	        case NpcAction::CallPolice: return "calls out for the police!";
122	        case NpcAction::ReturnHome:
123	        case NpcAction::None: return "";
124	    }
125	    return "";
126	}
127	
128	// Maps the NPC's core mood onto the renderer's face enum.
129	NpcFace faceForMood(NpcMood mood) {
130	    switch (mood) {
131	        case NpcMood::Happy: return NpcFace::Happy;
132	        case NpcMood::Angry: return NpcFace::Angry;
133	        case NpcMood::Sad: return NpcFace::Sad;
134	        case NpcMood::Embarrassed: return NpcFace::Embarrassed;
135	        case NpcMood::Surprised: return NpcFace::Surprised;
136	        case NpcMood::Neutral: return NpcFace::Neutral;
137	    }
138	    return NpcFace::Neutral;
139	}
140	
141	// Draws `str` centered horizontally at height `y` with a dark backdrop bar.
142	void drawCenteredHudText(const std::string& str, int size, float y) {
143	    const int width = MeasureText(str.c_str(), size);
144	    const float x = (static_cast<float>(GetScreenWidth()) - static_cast<float>(width)) * 0.5f;
145	    DrawRectangleRec(Rectangle{x - 12.f, y - 6.f, static_cast<float>(width) + 24.f,
146	                               static_cast<float>(size) + 16.f},
147	                     Color{10, 14, 22, 170});
148	    DrawText(str.c_str(), static_cast<int>(x), static_cast<int>(y), size, WHITE);
149	}
150	
151	// Nameplate: centered text with an outline-ish shadow at a projected point.
152	void drawNameplate(const std::string& name, Vector2 screen, Color color) {
153	    const int width = MeasureText(name.c_str(), 14);
154	    const int x = static_cast<int>(screen.x) - width / 2;
155	    const int y = static_cast<int>(screen.y) - 14;
156	    DrawText(name.c_str(), x + 1, y + 1, 14, Color{0, 0, 0, 200});
157	    DrawText(name.c_str(), x, y, 14, color);
158	}
159	
160	}  // namespace
161	
162	int main(int argc, char** argv) {
163	    // --frames N [shot.png] [--camera x z yaw] [--hour H]: render N frames
164	    // then exit 0, optionally saving a screenshot of the last frame
165	    // (scripted smoke runs + visual checks). --camera overrides the default
166	    // plaza vantage; --hour pins the world clock so day/night-dependent
167	    // screenshots stay deterministic.
168	    long maxFrames = -1;
169	    const char* screenshotPath = nullptr;
170	    bool cameraOverride = false;
171	    float cameraX = 0.f, cameraZ = 0.f, cameraYaw = 180.f;
172	    float hourOverride = -1.f;
173	    if (argc >= 3 && std::strcmp(argv[1], "--frames") == 0) {
174	        maxFrames = std::strtol(argv[2], nullptr, 10);
175	        int arg = 3;
176	        if (arg < argc && argv[arg][0] != '-') {
177	            screenshotPath = argv[arg++];
178	        }
179	        while (arg < argc) {
180	            if (arg + 3 < argc && std::strcmp(argv[arg], "--camera") == 0) {
181	                cameraOverride = true;
182	                cameraX = std::strtof(argv[arg + 1], nullptr);
183	                cameraZ = std::strtof(argv[arg + 2], nullptr);
184	                cameraYaw = std::strtof(argv[arg + 3], nullptr);
185	                arg += 4;
186	            } else if (arg + 1 < argc && std::strcmp(argv[arg], "--hour") == 0) {
187	                hourOverride = std::strtof(argv[arg + 1], nullptr);
188	                arg += 2;
189	            } else {
190	                ++arg;
191	            }
192	        }
193	    }
194	
195	    const fs::path projectRoot = findProjectRoot();
196	    const fs::path configDir = projectRoot / "config";
197	
198	    KeyBindings bindings = KeyBindings::defaults();
199	    const fs::path bindingsPath = configDir / "keybindings.cfg";
200	    bindings.load(bindingsPath);
201	
202	    // World: the downtown map plus one NPC per persona file.
203	    LlmClient client(loadLlmConfig(configDir));
204	    client.warmUp();  // preload the model so the first reply starts fast
205	    World world(City::makeDowntown());
206	    // Smoke runs pin the clock so day/night screenshots are deterministic.
207	    if (hourOverride >= 0.f) world.state().setTimeOfDayHours(hourOverride);
208	    std::vector<std::string> personaErrors;
209	    const auto roster = loadAllPersonas(projectRoot / "personas", &personaErrors);
210	    for (const auto& err : personaErrors) std::cerr << "[llm_npc] persona error: " << err << "\n";
211	    for (const auto& loaded : roster) {
212	        Npc npc(loaded.persona, client);
213	        npc.setPlacement(loaded.position, loaded.facingDeg, loaded.spotId);
214	        npc.setSchedule(loaded.schedule);
215	        world.addNpc(std::move(npc));
216	    }
217	
218	    // Player-created characters (plan: character-creator): the persona
219	    // record goes through the SAME parser as designer .persona files; the
220	    // look record is registered so the render loop draws the composite
221	    // instead of a pack model. Bad rows were already skipped by loadAll.
222	    CharacterStore characterStore(projectRoot / "saves" / "characters.sqlite3");
223	    std::unordered_map<std::size_t, CharacterLook> customLooks;
224	    for (const StoredCharacter& stored : characterStore.loadAll()) {
225	        const PersonaParseResult parsed =
226	            parsePersonaText(stored.personaText, stored.characterId);
227	        if (!parsed.ok) {
228	            std::cerr << "[llm_npc] stored persona error: " << parsed.error << "\n";
229	            continue;
230	        }
231	        Npc npc(parsed.value.persona, client);
232	        npc.setPlacement(parsed.value.position, parsed.value.facingDeg,
233	                         parsed.value.spotId);
234	        npc.setSchedule(parsed.value.schedule);
235	        customLooks[world.npcs().size()] = stored.look;
236	        world.addNpc(std::move(npc));
237	    }
238	    std::cerr << "[llm_npc] loaded " << world.npcs().size() << " NPCs ("
239	              << customLooks.size() << " player-created)\n";
240	
241	    // Cross-session NPC memory: summaries persist in saves/ and are injected
242	    // into each NPC's system prompt (plan: npc-memory-and-model).
243	    ConversationStore memoryStore(projectRoot / "saves" / "conversations.sqlite3");
244	    for (Npc& npc : world.npcs()) {
245	        const NpcMemory memory = memoryStore.load(npc.persona().name);
246	        if (!memory.summary.empty()) npc.setMemory(memory.summary);
247	    }
248	    // History length at the last save, per NPC — new turns above this mark
249	    // trigger a summarization request when the conversation closes.
250	    std::vector<std::size_t> savedTurns(world.npcs().size(), 0);
251	    // In-flight summary request id → NPC index it belongs to.
252	    std::unordered_map<std::uint64_t, int> summaryRoutes;
253	
254	    // Town gossip: structured facts on the world bus, persisted across
255	    // sessions (plan: gossip-facts). Facts and knowledge sets load before
256	    // the per-NPC gossip strings render below.
257	    FactStore factStore(projectRoot / "saves" / "facts.sqlite3");
258	    factStore.loadInto(world.state());
259	    // In-flight fact-extraction request id → NPC index it belongs to.
260	    std::unordered_map<std::uint64_t, int> factRoutes;
261	
262	    // Re-renders one NPC's gossip prompt block from the facts THAT NPC has
263	    // heard on the bus (knowledge is per-agent by design).
264	    const auto refreshGossip = [&](Npc& npc) {
265	        std::string gossip;
266	        for (const KnownFact* fact : world.state().factsKnownBy(npc.persona().name)) {
267	            gossip += fact->content + " (heard from " + fact->source + "). ";
268	        }
269	        npc.setGossip(std::move(gossip));
270	    };
271	    for (Npc& npc : world.npcs()) refreshGossip(npc);
272	
273	    // PROPOSE step of propose->validate->commit: after a conversation, ask
274	    // the NPC's own model for at most two structured facts as strict JSON.
275	    // The reply is validated by validateProposedFacts before anything is
276	    // committed to the bus — model output never writes directly.
277	    const auto requestFacts = [&](int npcIndex) {
278	        if (npcIndex < 0 || npcIndex >= static_cast<int>(world.npcs().size())) return;
279	        Npc& npc = world.npcs()[static_cast<std::size_t>(npcIndex)];
280	        if (npc.history().empty()) return;
281	        std::string transcript;
282	        for (const auto& turn : npc.history()) {
283	            transcript += (turn.role == "user" ? "Player: " : npc.persona().name + ": ");
284	            transcript += turn.content + "\n";
285	        }
286	        const std::uint64_t id = client.submit(
287	            "You extract concrete facts from a game conversation. Reply with "
288	            "ONLY a JSON array (no prose, no code fences) of at most 2 "
289	            "objects, each {\"subject\": short_topic, \"content\": one short "
290	            "sentence, \"direction\": \"npc_learned\" or \"player_learned\"}. "
291	            "npc_learned = the player told the character something new; "
292	            "player_learned = the character told the player something. Only "
293	            "specific, memorable facts — no pleasantries. Reply [] if none.",
294	            {}, "Conversation:\n" + transcript);
295	        factRoutes[id] = npcIndex;
296	    };
297	
298	    // Asks the NPC's own model to update its first-person memory note.
299	    const auto requestSummary = [&](int npcIndex) {
300	        if (npcIndex < 0 || npcIndex >= static_cast<int>(world.npcs().size())) return;
301	        Npc& npc = world.npcs()[static_cast<std::size_t>(npcIndex)];
302	        if (npc.history().size() <= savedTurns[static_cast<std::size_t>(npcIndex)]) return;
303	        std::string transcript;
304	        for (const auto& turn : npc.history()) {
305	            transcript += (turn.role == "user" ? "Player: " : npc.persona().name + ": ");
306	            transcript += turn.content + "\n";
307	        }
308	        std::string request =
309	            "You are " + npc.persona().name + ". Here is your conversation with the "
310	            "player so far:\n" + transcript;
311	        if (!npc.memory().empty()) {
312	            request += "You previously remembered: " + npc.memory() + "\n";
313	        }
314	        request +=
315	            "In at most 3 sentences, first person, write the updated note you keep "
316	            "about this player: who they are, what happened, anything to remember "
317	            "next time. Reply with the note only.";
318	        const std::uint64_t id = client.submit(
319	            "You write concise first-person memory notes for a game character. "
320	            "No preamble, no directives, just the note.",
321	            {}, std::move(request));
322	        summaryRoutes[id] = npcIndex;
323	    };
324	
