859	                    Npc& npc = world.npcs()[static_cast<std::size_t>(npcIndex)];
860	                    npc.setMemory(reply.content);
861	                    if (memoryStore.save(npc.persona().name, npc.memory(), npc.history())) {
862	                        savedTurns[static_cast<std::size_t>(npcIndex)] = npc.history().size();
863	                    }
864	                }  // failure: keep the old note; retry at the next close
865	                continue;
866	            }
867	            // Fact proposals: VALIDATE then COMMIT — a reply that isn't a
868	            // clean JSON array of well-formed facts commits nothing.
869	            if (const auto facts = factRoutes.find(reply.id); facts != factRoutes.end()) {
870	                const int npcIndex = facts->second;
871	                factRoutes.erase(facts);
872	                if (reply.ok && npcIndex >= 0 &&
873	                    npcIndex < static_cast<int>(world.npcs().size())) {
874	                    Npc& npc = world.npcs()[static_cast<std::size_t>(npcIndex)];
875	                    const auto proposals = validateProposedFacts(reply.content);
876	                    for (const ProposedFact& proposal : proposals) {
877	                        const KnownFact record =
878	                            commitFact(world.state(), proposal, npc.persona().name);
879	                        factStore.saveFact(record);
880	                        factStore.saveKnowledge(npc.persona().name, record.factId);
881	                        if (proposal.playerLearned) {
882	                            factStore.saveKnowledge("player", record.factId);
883	                        }
884	                    }
885	                    if (!proposals.empty()) refreshGossip(npc);
886	                }
887	                continue;
888	            }
889	            const auto route = pendingRoutes.find(reply.id);
890	            if (route == pendingRoutes.end()) continue;
891	            const int npcIndex = route->second;
892	            Npc& npc = world.npcs()[static_cast<std::size_t>(npcIndex)];
893	            const auto text = npc.onReplyArrived(reply);
894	            pendingRoutes.erase(route);
895	
896	            // Hosting: our own conversations broadcast the same speech/mood
897	            // updates remote-initiated ones do.
898	            if (chatRouter && text) {
899	                chatRouter->announceNpcSpeech(npcIndex, *text);
900	                chatRouter->announceNpcMood(npcIndex);
901	            }
902	
903	            if (session.replyArrived(reply.id, reply.ok)) {
904	                dialog.endStreaming();
905	                if (text) {
906	                    if (!text->empty()) {
907	                        dialog.appendLine({TranscriptLine::Kind::Npc, npc.persona().name, *text});
908	                    }
909	                    const std::string sd = stageDirection(npc.lastAction());
910	                    if (!sd.empty()) {
911	                        dialog.appendLine(
912	                            {TranscriptLine::Kind::System, "", npc.persona().name + " " + sd});
913	                    } else if (text->empty()) {
914	                        dialog.appendLine({TranscriptLine::Kind::System, "",
915	                                           "(" + npc.persona().name + " says nothing.)"});
916	                    }
917	                    // A summons mobilizes every officer in the city.
918	                    if (npc.lastAction() == NpcAction::CallPolice) {
919	                        for (Npc& officer : world.npcs()) {
920	                            if (officer.persona().police) officer.commandArrest();
921	                        }
922	                    }
923	                } else {
924	                    dialog.appendLine({TranscriptLine::Kind::System, "",
925	                                       "[" + npc.persona().name +
926	                                           " seems distracted: " + reply.errorMessage + "]"});
927	                }
928	                dialog.setInputEnabled(true);
929	            }
930	        }
931	
932	        // ---- render ----
933	        BeginDrawing();
934	        renderer.setTimeOfDay(worldHour);  // sky, fog, light: one clock
935	        ClearBackground(renderer.skyColor());
936	        renderer.beginFrame(CameraPose{player.position, player.yawDeg, player.pitchDeg});
937	        renderer.drawCity(world.city());
938	        if (joined) {
939	            for (const auto& netNpc : netNpcs) {
940	                CharacterVisual visual;
941	                visual.position = netNpc.position;
942	                visual.facingDeg = netNpc.facingDeg;
943	                visual.variantSeed = netNpc.npcIndex;
944	                const int mood = netNpc.npcIndex < static_cast<int>(netMoods.size())
945	                                     ? netMoods[static_cast<std::size_t>(netNpc.npcIndex)]
946	                                     : netNpc.mood;
947	                visual.face = faceForMood(static_cast<NpcMood>(mood));
948	                if (netNpc.npcIndex >= 0 &&
949	                    netNpc.npcIndex < static_cast<int>(world.npcs().size())) {
950	                    visual.police =
951	                        world.npcs()[static_cast<std::size_t>(netNpc.npcIndex)].persona().police;
952	                }
953	                renderer.drawCharacter(visual);
954	            }
955	        } else {
956	            for (std::size_t i = 0; i < world.npcs().size(); ++i) {
957	                const Npc& npc = world.npcs()[i];
958	                CharacterVisual visual;
959	                visual.position = npc.position();
960	                visual.facingDeg = npc.facingDeg();
961	                visual.variantSeed = static_cast<int>(i);
962	                visual.police = npc.persona().police;
963	                visual.walking = distanceXZ(npc.position(), npcLastPos[i]) > 0.01f;
964	                npcLastPos[i] = npc.position();
965	                if (npc.pose() != NpcAction::None) visual.gesturePhase = npc.gesturePhase();
966	                visual.face = faceForMood(npc.mood());
967	                visual.dead = npc.combatState() == NpcState::Dead;
968	                if (smokeRun) visual.face = static_cast<NpcFace>(i % 6);
969	                // Player-created characters draw as their socketed part
970	                // composite; everyone else uses a pack model.
971	                if (const auto customLook = customLooks.find(i);
972	                    customLook != customLooks.end()) {
973	                    renderer.drawCompositeCharacter(
974	                        customLook->second, npc.position(), npc.facingDeg(),
975	                        visual.walking, static_cast<float>(GetTime()));
976	                } else {
977	                    renderer.drawCharacter(visual);
978	                }
979	            }
980	        }
981	        // Fellow players, drawn with the character mesh (id offset picks a
982	        // variant no NPC uses).
983	        for (const auto& remote : remotePlayers) {
984	            CharacterVisual visual;
985	            visual.position = remote.position;
986	            visual.facingDeg = remote.facingDeg;
987	            visual.variantSeed = 1000 + remote.playerId;
988	            renderer.drawCharacter(visual);
989	        }
990	        // Creator preview: the draft look turns slowly a few steps in front
991	        // of the camera while the Creator page is open (the page's lighter
992	        // overlay keeps it readable).
993	        if (mode == AppMode::Menu && menu.creatorPreview()) {
994	            previewSpinDeg += dt * 35.f;
995	            const Vec3 previewAt = player.position + flatForward(player.yawDeg) * 3.4f;
996	            renderer.drawCompositeCharacter(*menu.creatorPreview(), previewAt,
997	                                            previewSpinDeg, false, 0.f);
998	        }
999	        if (!joined && mode != AppMode::Dead) {
1000	            renderer.drawViewmodel(static_cast<int>(world.player().weapon),
1001	                                   world.player().attackAnimFraction);
1002	        }
1003	        renderer.endFrame();
1004	
1005	        // ---- 2D overlay ----
1006	        // Nameplates from whichever pose source is authoritative right now.
1007	        const auto plateFor = [&](const Vec3& feet, const std::string& name, Color color) {
1008	            if (distanceXZ(player.position, feet) > kNameplateRange) return;
1009	            Vector2 screen;
1010	            if (!renderer.worldToScreen(feet + Vec3{0.f, 2.15f, 0.f}, screen)) return;
1011	            drawNameplate(name, screen, color);
1012	        };
1013	        if (joined) {
1014	            for (const auto& netNpc : netNpcs) {
1015	                if (netNpc.npcIndex < 0 ||
1016	                    netNpc.npcIndex >= static_cast<int>(world.npcs().size())) continue;
1017	                plateFor(netNpc.position,
1018	                         world.npcs()[static_cast<std::size_t>(netNpc.npcIndex)].persona().name,
1019	                         WHITE);
1020	            }
1021	        } else {
1022	            for (const Npc& npc : world.npcs()) {
1023	                // Nameplate carries the schedule activity ("Marge - baking
1024	                // bread") so the routine reads at a glance.
1025	                plateFor(npc.position(),
1026	                         npc.activity().empty()
1027	                             ? npc.persona().name
1028	                             : npc.persona().name + " - " + npc.activity(),
1029	                         WHITE);
1030	            }
1031	        }
1032	        for (const auto& remote : remotePlayers) {
1033	            plateFor(remote.position, remote.name, Color{150, 220, 255, 255});
1034	        }
1035	
1036	        // Combat callouts float above their NPC like temporary nameplates.
1037	        for (const auto& callout : callouts) {
1038	            if (callout.npcIndex < 0 ||
1039	                callout.npcIndex >= static_cast<int>(world.npcs().size())) continue;
1040	            const Npc& npc = world.npcs()[static_cast<std::size_t>(callout.npcIndex)];
1041	            Vector2 screen;
1042	            if (renderer.worldToScreen(npc.position() + Vec3{0.f, 2.6f, 0.f}, screen)) {
1043	                drawNameplate(callout.text, screen, Color{255, 200, 120, 255});
1044	            }
1045	        }
1046	
1047	        if (mode == AppMode::Playing) {
1048	            if (nearbyNpc >= 0 && nearbyNpc < static_cast<int>(world.npcs().size())) {
1049	                const Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
1050	                drawCenteredHudText(
1051	                    "[" + bindings.key(Action::Talk) + "] Talk to " + npc.persona().name, 20,
1052	                    static_cast<float>(GetScreenHeight()) - 84.f);
1053	            }
1054	            if (jailSecondsLeft > 0.f) {
1055	                const int secs = static_cast<int>(jailSecondsLeft) + 1;
1056	                drawCenteredHudText("Arrested: disturbing the peace. Released in " +
1057	                                        std::to_string(secs) + "s",
1058	                                    22, static_cast<float>(GetScreenHeight()) - 120.f);
1059	            }
1060	            DrawCircle(GetScreenWidth() / 2, GetScreenHeight() / 2, 2.f,
1061	                       Color{255, 255, 255, 200});
1062	            // Weapon + health HUD (bottom-left), solo/host only.
1063	            if (!joined) {
1064	                const Player& p = world.player();
1065	                const WeaponDef& def = weaponDef(p.weapon);
1066	                std::string weaponLine = std::string("[1/2] ") + def.name;
1067	                if (def.ammoMax > 0) {
1068	                    const auto it = p.ammo.find(static_cast<std::uint8_t>(p.weapon));
1069	                    weaponLine += "  ammo " +
1070	                                  std::to_string(it != p.ammo.end() ? it->second : 0);
1071	                }
1072	                DrawText(weaponLine.c_str(), 24, GetScreenHeight() - 64, 18, RAYWHITE);
1073	                DrawRectangle(24, GetScreenHeight() - 40, 180, 14, Color{40, 20, 20, 220});
1074	                DrawRectangle(24, GetScreenHeight() - 40,
1075	                              static_cast<int>(180.f * static_cast<float>(p.hp) /
1076	                                               static_cast<float>(p.hpMax)),
1077	                              14, Color{200, 60, 60, 255});
1078	            }
1079	        } else if (mode == AppMode::Dead) {
1080	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(), Color{40, 8, 8, 200});
1081	            const char* headline = "You died.";
1082	            DrawText(headline, (GetScreenWidth() - MeasureText(headline, 44)) / 2,
1083	                     GetScreenHeight() / 2 - 48, 44, RAYWHITE);
1084	            const char* hint = "Press Enter to wake up at the plaza.";
1085	            DrawText(hint, (GetScreenWidth() - MeasureText(hint, 20)) / 2,
1086	                     GetScreenHeight() / 2 + 12, 20, Color{220, 200, 200, 255});
1087	        } else if (mode == AppMode::Dialogue) {
1088	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(), Color{8, 10, 16, 150});
1089	            dialog.render();
1090	        } else {
1091	            menu.render();
1092	        }
1093	
1094	        if (hurtFlash > 0.f) {
1095	            const auto alpha = static_cast<unsigned char>(180.f * (hurtFlash / 0.35f));
1096	            DrawRectangle(0, 0, GetScreenWidth(), GetScreenHeight(),
1097	                          Color{200, 30, 30, alpha});
1098	        }
1099	        if (!assets.loaded()) {
1100	            DrawText("Asset packs missing - run tools/fetch_assets.sh for the full look", 24,
1101	                     GetScreenHeight() - 40, 18, Color{255, 225, 130, 255});
1102	        }
1103	        if (screenshotPath && maxFrames >= 0 && frames >= maxFrames) {
1104	            TakeScreenshot(screenshotPath);
1105	        }
1106	        EndDrawing();
1107	    }
1108	
1109	shutdown:
1110	    // Transcripts with unsaved turns persist on quit; their summary refresh
1111	    // happens at the next conversation close (summarizing here would block
1112	    // shutdown on the LLM).
1113	    for (std::size_t i = 0; i < world.npcs().size(); ++i) {
1114	        const Npc& npc = world.npcs()[i];
1115	        if (npc.history().size() > savedTurns[i]) {
1116	            memoryStore.save(npc.persona().name, npc.memory(), npc.history());
1117	        }
1118	    }
1119	
1120	    leaveSession();
1121	    CloseWindow();
1122	    return 0;
1123	}
