165	void RaylibRenderer::drawCity(const City& city) {
166	    const float half = city.halfSize();
167	
168	    // Ground: grass base with the street grid and block slabs on top.
169	    DrawPlane({0.f, 0.f, 0.f}, {half * 2.f, half * 2.f}, kGrass);
170	
171	    // Streets: KayKit road tiles when the pack is present, flat asphalt
172	    // strips otherwise. Tile pitch = street width (16), centers at multiples
173	    // of 16 so the four junctions at (+-32, +-32) land exactly on tile
174	    // centers; the arm tiles beside each junction (+-16, +-48) carry zebra
175	    // crossings where the sidewalks meet. 13 tiles cover +-104; a compressed
176	    // end-cap tile spans the last 6 units to the +-110 map edge.
177	    const Model* straight = assets_.prop("road_straight");
178	    const Model* crossing = assets_.prop("road_straight_crossing");
179	    const Model* junction = assets_.prop("road_junction");
180	    if (straight && crossing && junction) {
181	        constexpr float kTile = 16.f;
182	        for (const float sc : {-kStreetCenter, kStreetCenter}) {
183	            for (float t = -96.f; t <= 96.f; t += kTile) {
184	                if (t == -kStreetCenter || t == kStreetCenter) {
185	                    // Both streets pass through this tile; draw the 4-way
186	                    // junction art once (in the Z-running pass).
187	                    drawRoadTile(*junction, sc, t, kStreetWidth, kTile, false);
188	                    continue;
189	                }
190	                const float arm = std::fabs(std::fabs(t) - kStreetCenter);
191	                const Model& tile = (arm == kTile) ? *crossing : *straight;
192	                drawRoadTile(tile, sc, t, kStreetWidth, kTile, false);
193	                drawRoadTile(tile, t, sc, kTile, kStreetWidth, true);
194	            }
195	            for (const float e : {-107.f, 107.f}) {
196	                drawRoadTile(*straight, sc, e, kStreetWidth, 6.f, false);
197	                drawRoadTile(*straight, e, sc, 6.f, kStreetWidth, true);
198	            }
199	        }
200	    } else {
201	        for (const float c : {-kStreetCenter, kStreetCenter}) {
202	            DrawCube({c, 0.02f, 0.f}, kStreetWidth, 0.04f, half * 2.f, kAsphalt);
203	            DrawCube({0.f, 0.02f, c}, half * 2.f, 0.04f, kStreetWidth, kAsphalt);
204	        }
205	    }
206	    // Block slabs: plaza (center) is pale stone, park (north-east) stays
207	    // grass, every other block gets a sidewalk-toned slab.
208	    for (const float bx : {-64.f, 0.f, 64.f}) {
209	        for (const float bz : {-64.f, 0.f, 64.f}) {
210	            const bool plaza = bx == 0.f && bz == 0.f;
211	            const bool park = bx == 64.f && bz == 64.f;
212	            if (park) continue;
213	            DrawCube({bx, 0.04f, bz}, 48.f, 0.08f, 48.f, plaza ? kPlaza : kSidewalk);
214	        }
215	    }
216	
217	    // Street furniture (traffic lights, bushes) renders through the same
218	    // buildings pass below — City authors their positions AND colliders,
219	    // so nothing visible can be walk-through.
220	
221	    // Buildings and street props from the collision AABBs — the models scale
222	    // to fit the authoritative footprints, never the other way around.
223	    for (const Building& b : city.buildings()) {
224	        // The fountain is composed from primitives (no pack model). Must be
225	        // dispatched by id BEFORE the model lookup: modelForBuilding falls
226	        // back to a hashed generic building for uncurated ids.
227	        if (b.id == "fountain") {
228	            drawFountain(b, assets_.sizeSpecFor(b).worldHeight);
229	            continue;
230	        }
231	        if (const Model* model = assets_.modelForBuilding(b)) {
232	            const Assets::SizeSpec& spec = assets_.sizeSpecFor(b);
233	            if (spec.mode == Assets::SizeSpec::Mode::Uniform) {
234	                drawModelUniform(*model, (b.minX + b.maxX) * 0.5f,
235	                                 (b.minZ + b.maxZ) * 0.5f, spec.worldHeight, WHITE);
236	            } else {
237	                drawModelFittedToAABB(*model, b.minX, b.minZ, b.maxX, b.maxZ, b.height,
238	                                      WHITE);
239	            }
240	        } else {
241	            // Fallback primitive, tinted like the legacy renderer's boxes.
242	            const unsigned char tint =
243	                static_cast<unsigned char>(120 + (b.facadeKind * 37) % 90);
244	            const Vector3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f,
245	                                 (b.minZ + b.maxZ) * 0.5f};
246	            DrawCube(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
247	                     Color{tint, tint, static_cast<unsigned char>(tint + 20), 255});
248	            DrawCubeWires(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
249	                          Color{40, 45, 60, 255});
250	        }
251	    }
252	}
253	
254	void RaylibRenderer::drawCharacter(const CharacterVisual& visual) {
255	    const Assets::CharacterAsset* character =
256	        assets_.characterFor(visual.variantSeed, visual.police);
257	    if (!character) {
258	        // No pack: marker cylinder, same as the pre-asset placeholder.
259	        const Vec3& p = visual.position;
260	        DrawCylinder({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{200, 120, 80, 255});
261	        DrawCylinderWires({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{60, 30, 20, 255});
262	        return;
263	    }
264	
265	    // Pick the clip: death overrides everything, gestures interrupt,
266	    // then walk/idle by movement.
267	    int clip = visual.walking ? character->walk : character->idle;
268	    if (visual.gesturePhase > 0.f && character->gesture >= 0) clip = character->gesture;
269	    if (visual.dead && character->death >= 0) clip = character->death;
270	
271	    AnimState& state = anim_[visual.variantSeed];
272	    if (state.clip != clip) {
273	        state.clip = clip;
274	        state.time = 0.f;
275	    }
276	    state.time += GetFrameTime();
277	    if (clip >= 0 && clip < character->clipCount) {
278	        // raylib bakes glTF animations at ~60 samples/second; loop by frame.
279	        const ModelAnimation& animation = character->clips[clip];
280	        const int frame =
281	            static_cast<int>(state.time * 60.f) % (animation.frameCount > 0
282	                                                       ? animation.frameCount
283	                                                       : 1);
284	        // CPU skinning on the shared model right before this entity's draw,
285	        // so several entities can reuse one model with different clocks.
286	        UpdateModelAnimation(character->model, animation, frame);
287	    }
288	
289	    // Uniform height: scale so every character stands ~1.8 units tall, feet
290	    // on the ground, rotated to the game's facing convention (0 → +Z).
291	    const BoundingBox bb = GetModelBoundingBox(character->model);
292	    const float modelHeight = bb.max.y - bb.min.y;
293	    const float s = modelHeight > 0.f ? 1.8f / modelHeight : 1.f;
294	    const Vector3 position{visual.position.x, -bb.min.y * s, visual.position.z};
295	    DrawModelEx(character->model, position, Vector3{0.f, 1.f, 0.f}, visual.facingDeg,
296	                Vector3{s, s, s}, WHITE);
297	
298	    // Non-neutral moods float as an emote above the head — the same six
299	    // procedural faces the legacy renderer painted on, now billboarded.
300	    // The dead don't emote.
301	    if (!visual.dead && visual.face != NpcFace::Neutral) {
302	        DrawBillboard(camera_, assets_.faceTexture(visual.face),
303	                      Vector3{visual.position.x, 2.45f, visual.position.z}, 0.55f,
304	                      WHITE);
305	    }
306	}
307	
308	void RaylibRenderer::drawCompositeCharacter(const CharacterLook& look,
309	                                            const Vec3& position, float facingDeg,
310	                                            bool walking, float phase) {
311	    const AssembledLook assembled = assembleLook(look);
312	    if (!assembled.ok) {
313	        // Invalid/stale look: the same marker cylinder the pack path uses.
314	        DrawCylinder({position.x, 0.f, position.z}, 0.35f, 0.35f, 1.8f, 12,
315	                     Color{200, 120, 80, 255});
316	        return;
317	    }
318	    // ONE uniform scale takes the whole assembly to the same height
319	    // contract pack characters use — parts were snapped in local space, so
320	    // proportions and socket alignment survive any future contract change.
321	    const float s = 1.8f / assembled.height;
322	
323	    const PartPalette* palette = &paletteCatalog().front();
324	    for (const PartPalette& candidate : paletteCatalog()) {
325	        if (candidate.id == look.paletteId) palette = &candidate;
326	    }
327	    const Color skin{palette->skin[0], palette->skin[1], palette->skin[2], 255};
328	    const Color hair{palette->hair[0], palette->hair[1], palette->hair[2], 255};
329	    const Color outfit{palette->outfit[0], palette->outfit[1], palette->outfit[2], 255};
330	    const Color dark{38, 38, 44, 255};
331	
332	    // Whole-figure transform: facing + procedural walk bob. Parts then draw
333	    // at their assembly-local positions and rotate correctly for free.
334	    const float bob = walking ? std::fabs(std::sin(phase * 7.f)) * 0.05f : 0.f;
335	    rlPushMatrix();
336	    rlTranslatef(position.x, position.y + bob, position.z);
337	    rlRotatef(facingDeg, 0.f, 1.f, 0.f);
338	
339	    for (const PlacedPart& placed : assembled.parts) {
340	        const PartDef& part = *placed.part;
341	        const Vec3 at = placed.position * s;          // anchor, bottom-center
342	        const Vec3 dim = part.localSize * s;
343	        const float cy = at.y + dim.y * 0.5f;         // box center height
344	
345	        if (part.id == "body_round") {
346	            // Tapered trunk: narrow shoulders over a wider base.
347	            DrawCylinder({at.x, at.y, at.z}, dim.x * 0.34f, dim.x * 0.5f,
348	                         dim.y, 16, outfit);
349	        } else if (part.id == "head_round") {
350	            DrawSphere({at.x, cy, at.z}, dim.y * 0.5f, skin);
351	        } else if (part.id == "hair_tuft") {
352	            DrawSphere({at.x, at.y + dim.y * 0.3f, at.z}, dim.x * 0.5f, hair);
353	        } else if (part.id == "hair_bowl") {
354	            // Oversized cap sunk into the head reads as a bowl cut.
355	            DrawSphere({at.x, at.y - dim.y * 0.55f, at.z}, dim.x * 0.5f, hair);
356	        } else if (part.id == "hair_spikes") {
357	            for (int i = -1; i <= 1; ++i) {
358	                DrawCylinder({at.x + static_cast<float>(i) * dim.x * 0.30f,
359	                              at.y - dim.y * 0.25f, at.z},
360	                             0.f, dim.x * 0.16f, dim.y, 8, hair);
361	            }
362	        } else if (part.category == PartCategory::Eyes) {
363	            if (part.id == "eyes_visor") {
364	                DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, dark);
365	            } else {
366	                // Two pupils split across the part's declared width.
367	                const float dx = dim.x * 0.5f - dim.y * 0.5f;
368	                DrawSphere({at.x - dx, cy, at.z}, dim.y * 0.5f, dark);
369	                DrawSphere({at.x + dx, cy, at.z}, dim.y * 0.5f, dark);
370	            }
371	        } else if (part.localSize.y > 0.f) {
372	            // Generic recipe: any part without a bespoke shape renders as
373	            // its declared box (skin for heads, hair on top, outfit below)
374	            // so NEW catalog parts appear immediately, just plainly.
375	            const Color color = part.category == PartCategory::Head ? skin
376	                                : part.category == PartCategory::Hair ? hair
377	                                                                      : outfit;
378	            DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, color);
379	        }
380	    }
381	    rlPopMatrix();
382	}
