384	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
385	    // Per-weapon visuals live in this table; adding a WeaponKind means
386	    // adding a row, never a new code branch. Sizes are camera-space meters.
387	    struct ViewSpec {
388	        Vector3 size;        // main body (fist / gun body)
389	        Color color;
390	        float thrust;        // + pushes forward on attack (punch), - recoils
391	        bool grip;           // draw a pistol-style grip under the body
392	    };
393	    static const ViewSpec kSpecs[] = {
394	        {{0.11f, 0.09f, 0.14f}, Color{224, 172, 138, 255}, 0.45f, false},  // Fist
395	        {{0.05f, 0.07f, 0.30f}, Color{55, 58, 66, 255}, -0.14f, true},     // Pistol
396	    };
397	    const int count = static_cast<int>(sizeof(kSpecs) / sizeof(kSpecs[0]));
398	    if (weaponKind < 0 || weaponKind >= count) return;
399	    const ViewSpec& spec = kSpecs[weaponKind];
400	
401	    // Camera basis for a lower-right anchored prop.
402	    const Vector3 fwd{camera_.target.x - camera_.position.x,
403	                      camera_.target.y - camera_.position.y,
404	                      camera_.target.z - camera_.position.z};
405	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
406	    if (flen < 1e-4f) return;
407	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
408	    // Same right-vector convention as the game's strafe (flatRight in
409	    // main.cpp): cross(forward, up) = (-fz, 0, fx).
410	    const Vector3 r{-f.z, 0.f, f.x};
411	
412	    const float push = spec.thrust * attackFraction;
413	    const Vector3 base{
414	        camera_.position.x + f.x * (0.85f + push) + r.x * 0.32f,
415	        camera_.position.y - 0.28f + f.y * (0.85f + push),
416	        camera_.position.z + f.z * (0.85f + push) + r.z * 0.32f};
417	
418	    DrawCubeV(base, spec.size, spec.color);
419	    if (spec.grip) {
420	        DrawCubeV(Vector3{base.x - f.x * 0.10f, base.y - 0.07f, base.z - f.z * 0.10f},
421	                  Vector3{0.045f, 0.10f, 0.06f}, spec.color);
422	    }
423	}
424	
425	void RaylibRenderer::endFrame() {
426	    if (assets_.fogShader()) EndShaderMode();
427	    EndMode3D();
428	}
429	
430	bool RaylibRenderer::worldToScreen(const Vec3& world, Vector2& out) const {
431	    // Reject points behind the camera: GetWorldToScreen would mirror them.
432	    const Vector3 toPoint{world.x - camera_.position.x, world.y - camera_.position.y,
433	                          world.z - camera_.position.z};
434	    const Vector3 forward{camera_.target.x - camera_.position.x,
435	                          camera_.target.y - camera_.position.y,
436	                          camera_.target.z - camera_.position.z};
437	    if (toPoint.x * forward.x + toPoint.y * forward.y + toPoint.z * forward.z <= 0.f) {
438	        return false;
439	    }
440	    out = GetWorldToScreen({world.x, world.y, world.z}, camera_);
441	    return true;
442	}
443	
444	}  // namespace llm_npc
