12	bool World::playerAttack(const Vec3& aimDirection) {
13	    if (player_.attackCooldown > 0.f) return false;
14	
15	    const WeaponDef& def = weaponDef(player_.weapon);
16	
17	    if (player_.weapon == WeaponKind::Fist) {
18	        const int target = nearestNpcWithin(player_.position, def.range);
19	        player_.attackCooldown    = def.fireCooldown;
20	        player_.attackAnimFraction = 1.0f;
21	        if (target < 0) return true;  // swing missed — cooldown still consumed
22	        npcs_[static_cast<std::size_t>(target)].takeDamage(def.damage);
23	        return true;
24	    }
25	
26	    // Pistol: check ammo, spawn a projectile.
27	    auto& ammoSlot = player_.ammo[static_cast<std::uint8_t>(player_.weapon)];
28	    if (ammoSlot <= 0) return false;
29	
30	    --ammoSlot;
31	    player_.attackCooldown    = def.fireCooldown;
32	    player_.attackAnimFraction = 1.0f;
33	
34	    const Vec3 dir = normalize(Vec3{aimDirection.x, 0.f, aimDirection.z});
35	    Projectile p;
36	    p.position   = player_.position;
37	    p.direction  = dir;
38	    p.speed      = 40.f;
39	    p.damage     = def.damage;
40	    p.fromPlayer = true;
41	    projectiles_.push_back(p);
42	    return true;
43	}
44	
45	void World::playerSwitchWeapon(WeaponKind kind) {
46	    if (weaponDef(kind).ammoMax > 0) {
47	        const auto it = player_.ammo.find(static_cast<std::uint8_t>(kind));
48	        if (it == player_.ammo.end() || it->second == 0) return;
49	    }
50	    player_.weapon = kind;
51	}
52	
53	CombatFrameResult World::updateCombat(float dt) {
54	    CombatFrameResult result;
55	    tickCooldowns(dt);
56	    tickProjectiles(dt, result);
57	    tickNpcAi(dt, result);
58	    return result;
59	}
60	
61	void World::tickProjectiles(float dt, CombatFrameResult& out) {
62	    static constexpr float kNpcRadius = 0.4f;
63	    static constexpr float kNpcHeight = 1.8f;
64	
65	    for (auto& proj : projectiles_) {
66	        proj.position += proj.direction * (proj.speed * dt);
67	        proj.lifetime += dt;
68	    }
69	
70	    auto it = projectiles_.begin();
71	    while (it != projectiles_.end()) {
72	        if (it->lifetime >= it->maxLifetime) {
73	            it = projectiles_.erase(it);
74	            continue;
75	        }
76	
77	        bool hit = false;
78	        for (std::size_t i = 0; i < npcs_.size(); ++i) {
79	            Npc& npc = npcs_[i];
80	            if (npc.combatState() == NpcState::Dead) continue;
81	            if (!it->fromPlayer) continue;  // NPC projectiles hit player only
82	
83	            const float xzDist = distanceXZ(it->position, npc.position());
84	            if (xzDist > kNpcRadius) continue;
85	            if (it->position.y < 0.f || it->position.y > kNpcHeight) continue;
86	
87	            const bool killed = (npc.hp() - it->damage <= 0);
88	            npc.takeDamage(it->damage);
89	            out.npcsDamaged.push_back({i, it->damage, killed});
90	            out.shotsFired.push_back({true, i, it->damage});
91	            hit = true;
92	            break;
93	        }
94	
95	        if (hit) {
96	            it = projectiles_.erase(it);
97	        } else {
98	            ++it;
99	        }
100	    }
101	}
102	
103	void World::tickNpcAi(float dt, CombatFrameResult& out) {
104	    for (std::size_t i = 0; i < npcs_.size(); ++i) {
105	        Npc& npc = npcs_[i];
106	        switch (npc.combatState()) {
107	            case NpcState::Fleeing: {
108	                const Vec3 away = normalize(npc.position() - player_.position);
109	                const Vec3 target = npc.position() + away * (kFleeSpeed * dt);
110	                npc.position() = city_.resolveMovement(npc.position(), target, 0.4f);
111	                break;
112	            }
113	            case NpcState::Hostile: {
114	                const float dist = distanceXZ(npc.position(), player_.position);
115	                const Vec3 dir   = normalize(player_.position - npc.position());
116	                if (dist > kHostilePreferRange + 1.f) {
117	                    const Vec3 target = npc.position() + dir * (kFleeSpeed * dt);
118	                    npc.position() = city_.resolveMovement(npc.position(), target, 0.4f);
119	                } else if (dist < kHostilePreferRange - 1.f) {
120	                    const Vec3 target = npc.position() - dir * (kFleeSpeed * dt);
121	                    npc.position() = city_.resolveMovement(npc.position(), target, 0.4f);
122	                }
123	                if (npc.fireCooldown <= 0.f) {
124	                    npc.fireCooldown = kNpcFireCooldownMin +
125	                        std::uniform_real_distribution<float>(
126	                            0.f, kNpcFireCooldownMax - kNpcFireCooldownMin)(rng_);
127	                    const bool landed =
128	                        std::uniform_real_distribution<float>(0.f, 1.f)(rng_) < kNpcHitChance;
129	                    const int dmg = landed ? weaponDef(WeaponKind::Pistol).damage : 0;
130	                    out.npcShots.push_back({i, landed, dmg});
131	                    if (landed) {
132	                        player_.hp = std::max(0, player_.hp - dmg);
133	                    }
134	                }
135	                break;
136	            }
137	            default:
138	                break;
